(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const out = {};

  // 文件由 --file-input 塞进「打开作品」，等导入完成、提示弹出
  for (let i = 0; i < 40; i++) {
    await sleep(500);
    if (document.querySelector('.il-modal') || document.querySelector('.pj-toast') || document.querySelector('.tb-error')) break;
  }
  out.openedWork = document.querySelector('.pj-title')?.textContent || null;

  // ① 提示内容
  out.promptTitle = document.querySelector('.il-modal h2')?.textContent || null;
  out.promptItems = [...document.querySelectorAll('.il-item .il-name')].map((e) => e.textContent);
  out.promptButtons = [...document.querySelectorAll('.il-foot .il-btn')].map((b) => b.textContent.trim());
  out.promptImgOk = [...document.querySelectorAll('.il-item img')].filter((i) => i.naturalWidth > 0).length;

  // ② 确认之前，元件库不该被写入
  out.libraryBeforeConfirm = (await s.listLibrary()).length;

  // ③ 点「全部加入我的元件库」
  [...document.querySelectorAll('.il-foot .il-btn')].find((b) => b.textContent.includes('全部加入'))?.click();
  await sleep(2000);
  const lib = await s.listLibrary();
  out.libraryAfterConfirm = lib.length;
  out.added = lib.filter((c) => c.source !== 'builtin').map((c) => ({ id: c.id, from: c.fromProject, img: !!c.imageUrl }));
  out.promptGone = !document.querySelector('.il-modal');
  out.toast = document.querySelector('.pj-toast')?.textContent || document.querySelector('.tb-ok')?.textContent || null;
  return JSON.stringify(out);
})()
